// rust_certinfo/src/crypto/test_vectors.rs
//
// Keys, digests, and signatures produced with the OpenSSL CLI
// (`openssl dgst -sign`) over the message "certmonitor verifies
// signatures", shared by the crypto and verify unit tests.

#![cfg(test)]

pub fn hex(text: &str) -> Vec<u8> {
    let digits: String = text.chars().filter(|c| !c.is_whitespace()).collect();
    (0..digits.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&digits[i..i + 2], 16).unwrap())
        .collect()
}

